@public
class FractionField(Field, CompositeDomain):
    """Domain for multivariate rational function fields.

    Summary
    -------
    Represents a field of multivariate rational functions (fractions of
    multivariate polynomials) over a specified coefficient domain. This class
    wraps an underlying :class:`sympy.polys.fields.FracField` instance and
    exposes it through the Domain/CompositeDomain interface used by SymPy's
    polynomial machinery.

